const KEY='ffvii-field-guide-v1';
const defaults=()=>({version:1,chapter:'c1',checks:{},owned:{},notes:{},hideFuture:false,revealed:0,missables:{},roster:{},stables:makeStables(),breedingChecks:{},caves:{},details:{}});
let state=defaults(),storageOK=true;
try{const raw=localStorage.getItem(KEY);if(raw)state=normalize(JSON.parse(raw));}catch{storageOK=false;}
let view='guide',disc=C.find(c=>c.id===state.chapter).disc,tab='route',questId=null,bossTab='tactics',matType='All',matSearch='',matOwned=false;
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function normalize(raw){if(!raw||typeof raw!=='object'||raw.version!==1)throw Error('Unsupported backup');const s=defaults();s.chapter=C.some(c=>c.id===raw.chapter)?raw.chapter:'c1';s.hideFuture=raw.hideFuture===true;s.revealed=Math.max(0,Math.min(C.length-1,Number(raw.revealed)||0));const keys=new Set([...C,...Q].flatMap(c=>[...c.steps.map((_,i)=>c.id+'-s'+i),...(c.loot||[]).map((_,i)=>c.id+'-l'+i)]));for(const [k,v]of Object.entries(raw.checks||{}))if(keys.has(k)&&v===true)s.checks[k]=true;for(const m of M)if(raw.owned?.[m.id]===true)s.owned[m.id]=true;for(const c of [...C,...Q])if(typeof raw.notes?.[c.id]==='string')s.notes[c.id]=raw.notes[c.id].slice(0,30000);for(const a of ALERTS)if(['done','missed','skipped'].includes(raw.missables?.[a.id]))s.missables[a.id]=raw.missables[a.id];for(const p of PARTY)if(raw.roster?.[p.id]===true)s.roster[p.id]=true;for(let i=0;i<6;i++){const r=raw.stables?.[i];if(!r||typeof r!=='object')continue;const t=s.stables[i];t.name=typeof r.name==='string'?r.name.slice(0,40):'';if(['Empty','Good yellow','Great yellow','Wonderful yellow','Blue','Green','Black','Gold'].includes(r.breed))t.breed=r.breed;if(['Unknown','Male','Female'].includes(r.sex))t.sex=r.sex;t.wins=Math.max(0,Math.min(999,Number(r.wins)||0));t.ready=r.ready===true;}for(let i=0;i<BREED_STEPS.length;i++)if(raw.breedingChecks?.[i]===true)s.breedingChecks[i]=true;for(let i=0;i<4;i++)if(raw.caves?.[i]===true)s.caves[i]=true;for(const [k,v]of Object.entries(raw.details||{}))if(/^c[0-9]+-s[0-9]+-d[0-9]+$/.test(k)&&typeof v==='boolean')s.details[k]=v;return s;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('#saveStatus').textContent=storageOK?'Saved on this device':'Storage unavailable · export to save';}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2700);}
function checked(c){return c.steps.filter((_,i)=>state.checks[c.id+'-s'+i]).length;}
function isDone(c){return checked(c)===c.steps.length;}
function total(){const all=C.reduce((n,c)=>n+c.steps.length,0),done=C.reduce((n,c)=>n+checked(c),0);return {all,done,pct:Math.round(done/all*100)};}
function title(c){return state.hideFuture&&C.indexOf(c)>state.revealed?'Undiscovered chapter':c.title;}
function current(){return C.find(c=>c.id===state.chapter)||C[0];}
function openChapter(id){if(!C.some(c=>c.id===id))return;state.chapter=id;state.revealed=Math.max(state.revealed,C.findIndex(c=>c.id===id));disc=current().disc;view='guide';tab='route';bossTab='tactics';save();history.replaceState(null,'','#'+id);$('#sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'instant'});}
function nav(v){view=v;questId=null;history.replaceState(null,'','#'+(v==='guide'?state.chapter:v));render();window.scrollTo({top:0,behavior:'instant'});}
function openQuest(id){if(!Q.some(q=>q.id===id))return;view='quests';questId=id;history.replaceState(null,'','#'+id);render();window.scrollTo({top:0,behavior:'instant'});}
function renderAside(){document.querySelectorAll('[data-disc]').forEach(b=>{b.classList.toggle('selected',+b.dataset.disc===disc);b.setAttribute('aria-pressed',+b.dataset.disc===disc)});const q=$('#chapterSearch').value.trim().toLowerCase();const list=C.filter(c=>c.disc===disc&&(!q||title(c).toLowerCase().includes(q)||(!state.hideFuture&&c.area.toLowerCase().includes(q))));let group='';$('#chapterList').innerHTML=list.length?list.map(c=>{let g=c.disc===1?(C.indexOf(c)<8?'BENEATH THE PLATE':'BEYOND MIDGAR'):c.disc===2?(C.indexOf(c)<24?'NORTHWARD':'THE HUGE MATERIA & RETURN'):'THE FINAL CHAPTER';let label=g!==group?'<div class="region-label">'+g+'</div>':'';group=g;return label+`<button class="chapter-link ${c.id===state.chapter?'active':''}" data-chapter="${c.id}" ${c.id===state.chapter?'aria-current="step"':''}><span class="num">${String(C.indexOf(c)+1).padStart(2,'0')}</span><span>${esc(title(c))}</span><span class="small-check ${isDone(c)?'done':''}">${isDone(c)?'✓':''}</span></button>`}).join(''):'<div class="empty">No chapters found on this disc.</div>';}
function meteorMark(){return `<svg viewBox="0 0 100 70" aria-hidden="true"><path d="M23 40Q52 4 98 2Q70 22 47 50L32 55Z" fill="currentColor" opacity=".5"/><path d="M27 41Q58 14 89 8Q61 31 43 51" fill="currentColor" opacity=".75"/><circle cx="27" cy="47" r="20" fill="currentColor"/><path d="M12 49Q19 32 35 36" fill="none" stroke="#d8fff7" stroke-width="2" opacity=".7"/></svg>`;}
function cityArt(){return `<img class="hero-art" src="assets/midgar-arrival.jpg" alt="Cloud, carrying the Buster Sword, faces Midgar’s immense mako-lit skyline. Original illustration inspired by the 1997 game." width="1983" height="793" fetchpriority="high">`;}
function hero(c){const opening=c.id==='c1';return `<div class="breadcrumb"><span>The original journey</span><span>›</span><span>Disc ${c.disc}</span><span>›</span><b>Chapter ${String(C.indexOf(c)+1).padStart(2,'0')}</b></div><section class="hero ${opening?'opening-hero':''}">${cityArt()}<div class="hero-copy"><div class="edition-line"><span></span>1997 · THE ORIGINAL PLAYSTATION ADVENTURE</div><div class="game-lockup"><span class="lockup-meteor">${meteorMark()}</span><span>FINAL FANTASY <strong>VII</strong></span><small>THE COMPLETE FIELD GUIDE</small></div>${opening?'<p class="cover-line">A city without a sky.<br>A world worth saving.</p>':''}<div class="chapter-kicker"><span class="live-dot"></span> DISC ${c.disc} / CHAPTER ${String(C.indexOf(c)+1).padStart(2,'0')}</div><h1>${esc(c.title)}</h1><p class="hero-summary">${esc(c.summary)}</p><div class="hero-tags"><span>◇ ${c.steps.length} objectives</span><span>◈ ${c.loot.length} pickups</span><span>▱ Your progress, remembered.</span></div></div><span class="hero-number">THE PLANET’S FATE IS IN YOUR HANDS.</span><div class="hero-bottom-rule"></div></section>`;}
function stats(c){const t=total(),n=checked(c),loot=c.loot.filter((_,i)=>state.checks[c.id+'-l'+i]).length;return `<div class="stats"><div class="stat"><div class="stat-icon progress-ring" style="--p:${t.pct}"><span>${t.pct}%</span></div><div><b>Your journey</b><small>${t.done} of ${t.all} story objectives</small></div></div><div class="stat"><div class="stat-icon">✓</div><div><b>${n} / ${c.steps.length} complete</b><small>This chapter’s objectives</small></div></div><div class="stat"><div class="stat-icon">◇</div><div><b>${loot} / ${c.loot.length} collected</b><small>Chapter’s key pickups</small></div></div></div>`;}
function stepHTML(c){return `<div class="steps">${c.steps.map((s,i)=>`<div class="step ${state.checks[c.id+'-s'+i]?'checked':''}"><input id="${c.id}-step-${i}" type="checkbox" data-check="${c.id}-s${i}" ${state.checks[c.id+'-s'+i]?'checked':''} aria-label="Complete: ${esc(s[0])}"><div class="step-body"><h3><label for="${c.id}-step-${i}"><span class="step-no">${String(i+1).padStart(2,'0')}</span>${esc(s[0])}</label></h3><p>${esc(s[1])}</p>${detailedHTML(c,i)}</div></div>`).join('')}</div>`;}
function lootHTML(c){return c.loot.length?c.loot.map((l,i)=>`<label class="loot-row"><input type="checkbox" data-check="${c.id}-l${i}" ${state.checks[c.id+'-l'+i]?'checked':''} aria-label="Collected: ${esc(l[0])}"><div><b>${esc(l[0])}</b><span class="pill ${l[3]==='missable'?'missable':''}">${esc(l[3])}</span><p>${esc(l[2])}</p><small>↳ ${esc(l[1])}</small></div></label>`).join(''):'<p class="no-loot">No selected key pickups in this chapter. Check the route for shops, consumables and optional stops.</p>';}
function bossHTML(c){if(!c.boss)return `<div class="card"><span class="eyebrow">BEFORE YOU MOVE ON</span><h3 style="margin-top:15px">A little preparation goes far.</h3><p>Keep healing on more than one character. Check linked slots, save at safe points, and use a new save slot before a one-way sequence.</p></div>`;let b=c.boss;return `<section class="card boss-card"><span class="eyebrow">ENCOUNTER INTEL</span><div class="boss-icon">⚔</div><h3>${esc(b.name)}</h3><div class="boss-details"><div><small>HP</small><b>${esc(b.hp)}</b></div><div><small>FIELD INTEL</small><b>${esc(b.element)}</b></div></div><div class="boss-tabs"><button data-boss="tactics" class="${bossTab==='tactics'?'active':''}">Battle strategy</button><button data-boss="prep" class="${bossTab==='prep'?'active':''}">Loadout</button></div><p class="boss-text">${esc(bossTab==='prep'?b.prep:b.tactic)}</p></section>`;}
function guide(){const c=current(),i=C.indexOf(c),n=checked(c),next=C[i+1];let content=tab==='route'?stepHTML(c):tab==='loot'?lootHTML(c):tab==='notes'?`<textarea class="chapter-note" data-note="${c.id}" aria-label="Your chapter notes" placeholder="Your party setup, something to revisit, a reminder for later…">${esc(state.notes[c.id]||'')}</textarea><small class="library-count">Autosaved on this device.</small>`:focusHTML(c);return hero(c)+stats(c)+arrivalHTML(c)+chapterWarnings(c)+`<div class="content-grid"><section><div class="section-heading"><h2>Walkthrough</h2><button class="mark-all" data-complete="${c.id}">${isDone(c)?'Uncheck chapter':'Complete chapter'}</button></div><div class="subnav" aria-label="Chapter sections">${[['route','Walkthrough'],['loot','Key pickups'+(c.loot.length?' · '+c.loot.length:'')],['focus','Focus'],['notes','My notes']].map(([id,l])=>`<button data-tab="${id}" class="${tab===id?'active':''}" aria-pressed="${tab===id}">${l}</button>`).join('')}</div><div id="chapterContent">${isDone(c)&&tab==='route'?'<div class="completion-banner">✓ Chapter objectives complete. Check your pickups before moving on.</div>':''}${content}</div><div class="chapter-pagination"><button data-chapter="${C[i-1]?.id||''}" ${i===0?'disabled':''}>← Previous chapter</button><button data-chapter="${next?.id||c.id}">${next?'Next chapter →':'Review final chapter →'}</button></div></section><section class="right-rail" aria-label="Chapter reference">${bossHTML(c)}${c.note?`<div class="card tip-card"><span class="eyebrow">✧ &nbsp; FIELD NOTE</span><p>${esc(c.note)}</p></div>`:''}<div class="card"><div class="section-heading"><h3 style="margin:0">Chapter progress</h3><span>${Math.round(n/c.steps.length*100)}%</span></div><div class="progress-line"><div style="width:${n/c.steps.length*100}%"></div></div><p>${n===c.steps.length?'All route objectives checked.':c.steps.length-n+' objectives left. One step at a time.'}</p></div>${next?`<button class="card next-card" data-chapter="${next.id}"><small>NEXT CHAPTER</small><b>${esc(title(next))}</b><span>↗</span></button>`:`<div class="card"><span class="eyebrow">THE JOURNEY CONTINUES</span><p>Explore optional quests, complete your collection, or export your journal.</p><button class="button" data-view="quests">Explore side quests →</button></div>`}</section></div>`;}
function focusHTML(c){const i=c.steps.findIndex((_,i)=>!state.checks[c.id+'-s'+i]);if(i<0)return '<div class="completion-banner">✓ All objectives complete. Your next chapter is waiting.</div>';return `<div class="focus-box"><span class="eyebrow">YOUR NEXT OBJECTIVE · ${i+1} OF ${c.steps.length}</span><h3>${esc(c.steps[i][0])}</h3><p>${esc(c.steps[i][1])}</p>${detailedHTML(c,i)}<button class="button primary" data-focus-check="${c.id}-s${i}">Mark complete & continue →</button></div><p class="fine">Focus shows one objective at a time. Full chapter and pickup details remain in the other tabs.</p>`;}
function quests(){if(questId){const q=Q.find(x=>x.id===questId);return `<div class="quest-detail">${q.id==='q4'?'<div class="notice">The dedicated Chocobos section includes the detailed handbook, six-stall log and pairing checker. <button class="button" data-view="chocobos">Open the breeding handbook →</button></div>':''}<button class="back-button" data-back-quests>← All side quests</button><div class="view-heading"><span class="eyebrow">${esc(q.tag.toUpperCase())} / ${esc(q.unlock)}</span><h1>${esc(q.title)}</h1><p>${esc(q.summary)}</p></div><div class="section-heading"><span>${checked(q)} / ${q.steps.length} objectives complete</span><button class="mark-all" data-complete="${q.id}">${isDone(q)?'Uncheck quest':'Complete quest'}</button></div><div class="progress-line"><div style="width:${checked(q)/q.steps.length*100}%"></div></div>${stepHTML(q)}<h3>My field notes</h3><textarea class="chapter-note" data-note="${q.id}" aria-label="Quest notes" placeholder="Leave yourself a reminder…">${esc(state.notes[q.id]||'')}</textarea></div>`;}return `<div class="view-heading"><span class="eyebrow">OFF THE BEATEN PATH</span><h1>There’s more to this world.</h1><p>Optional companions, hidden places, and challenges worth coming back for.<br>These pages contain gameplay spoilers. Take them at your own pace.</p></div><div class="section-heading"><span>${Q.filter(isDone).length} / ${Q.length} quest routes complete</span><span>Progress saved automatically</span></div><div class="quest-grid">${Q.map(q=>`<article class="card quest-tile"><span class="eyebrow">${esc(q.tag)} ${isDone(q)?'· ✓ COMPLETE':''}</span><h3>${esc(q.title)}</h3><p>${esc(q.summary)}</p><div class="quest-bottom"><span>${checked(q)} / ${q.steps.length} objectives</span><span class="chevron">↗</span></div><button data-quest="${q.id}" aria-label="Open ${esc(q.title)}"></button></article>`).join('')}</div>`;}
function materia(){return `<div class="view-heading"><span class="eyebrow">THE PLANET’S MEMORY</span><h1>A little magic. A lot of possibility.</h1><p>A practical collection of ${M.length} useful Materia, where to find them, and what they do.<br>Mark what you own. Collection checks are separate from your chapter pickups.</p></div><div class="section-heading"><span id="matCount">${Object.values(state.owned).filter(Boolean).length} / ${M.length} collected</span><span>Locations may reveal future areas</span></div><div class="toolbar"><input id="matSearch" value="${esc(matSearch)}" placeholder="Search name, location, or ability…" aria-label="Search Materia"><select id="matType" aria-label="Filter Materia type">${['All','Magic','Support','Command','Independent','Summon'].map(t=>`<option ${matType===t?'selected':''}>${t}</option>`).join('')}</select><label><input id="matOwned" type="checkbox" ${matOwned?'checked':''}> Still to find</label></div><div class="materia-grid" id="materiaGrid">${materiaTiles()}</div>`;}
function materiaTiles(){let ms=M.filter(m=>(matType==='All'||m.type===matType)&&(!matOwned||!state.owned[m.id])&&[m.name,m.type,m.location,m.ability,m.tip].join(' ').toLowerCase().includes(matSearch.toLowerCase()));return ms.length?ms.map(m=>`<article class="card materia-tile"><div class="materia-top"><span class="orb ${m.type}" aria-hidden="true"></span><div><h3>${esc(m.name)}</h3><small>${esc(m.type)}</small></div></div><p class="location">↳ ${esc(m.location)}</p><p><b>${esc(m.ability)}</b></p><p>${esc(m.tip)}</p><label><input type="checkbox" data-owned="${m.id}" ${state.owned[m.id]?'checked':''}> ${state.owned[m.id]?'In my collection':'Mark as collected'}</label></article>`).join(''):'<div class="empty">No Materia match these filters.</div>';}
function journey(){const t=total();return `<div class="view-heading"><span class="eyebrow">FROM MIDGAR TO THE CRATER</span><h1>Every journey begins somewhere.</h1><p>A chapter route through the original game. Select any stop to open its walkthrough.<br>This is a progression map, rather than an in-game navigation map.</p></div><div class="journey-hero"><div><span class="eyebrow">YOUR STORY SO FAR</span><h2>${t.pct}% of the road traveled.</h2><p>${C.filter(isDone).length} of ${C.length} chapters complete · ${t.done} objectives checked</p></div><button class="button primary" data-chapter="${state.chapter}">Continue ${esc(current().title)} →</button></div><div class="journey-grid">${[1,2,3].map(d=>`<section class="journey-column"><span class="eyebrow">DISC ${d}</span><h2>${['','A world beyond the plate','A planet in peril','The final descent'][d]}</h2>${C.filter(c=>c.disc===d).map(c=>`<div class="journey-node ${c.id===state.chapter?'current':''} ${isDone(c)?'done':''}"><button data-chapter="${c.id}">${esc(title(c))}<small>${isDone(c)?'✓ Complete':checked(c)+' / '+c.steps.length+' objectives'}</small></button></div>`).join('')}</section>`).join('')}</div>`;}
function render(){renderAside();document.querySelectorAll('header [data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});$('#page').innerHTML=view==='guide'?guide():view==='quests'?quests():view==='materia'?materia():view==='journey'?journey():extraView();document.title=(view==='guide'?current().title:view==='quests'&&questId?Q.find(q=>q.id===questId).title:{quests:'Side quests',materia:'Materia collection',journey:'The journey',missables:'Items & events',chocobos:'Chocobo breeding',characters:'Character recruitment'}[view])+' · FFVII Field Guide';$('#saveStatus').textContent=storageOK?'Saved on this device':'Storage unavailable · export to save';}
function changeCheck(key,value){state.checks[key]=value;for(const c of C)for(const [i,rows]of Object.entries(c.details||{}))if(key===c.id+'-s'+i)rows.forEach((_,j)=>state.details[key+'-d'+j]=value);for(const a of ALERTS)if(a.key===key){if(value)state.missables[a.id]='done';else delete state.missables[a.id];}save();const focus=document.activeElement?.dataset?.check;render();if(focus)document.querySelector(`[data-check="${focus}"]`)?.focus({preventScroll:true});}
function search(){const q=$('#globalSearch').value.trim().toLowerCase();if(q.length<2){$('#searchResults').innerHTML='<div class="empty">Search chapter titles, objectives, pickups, quests and Materia.<br>Enter at least two characters. Future chapter results respect your spoiler setting.</div>';return;}const rs=[];for(const c of C){if(state.hideFuture&&C.indexOf(c)>state.revealed)continue;if([c.title,c.area,c.summary,...c.steps.flat(),...c.loot.flat(),...(c.arrival||[]).flat(),...Object.values(c.details||{}).flat(2)].join(' ').toLowerCase().includes(q))rs.push({kind:'chapter',id:c.id,name:c.title,detail:'Disc '+c.disc+' · Chapter '+(C.indexOf(c)+1)});}for(const x of Q)if([x.title,x.summary,...x.steps.flat()].join(' ').toLowerCase().includes(q))rs.push({kind:'quest',id:x.id,name:x.title,detail:'Side quest · '+x.unlock});for(const a of ALERTS)if([a.name,a.window,a.action,a.recovery].join(' ').toLowerCase().includes(q))rs.push({kind:'alert',id:a.id,name:a.name,detail:a.risk+' · '+a.window});for(const p of PARTY)if([p.name,p.when,p.how].join(' ').toLowerCase().includes(q))rs.push({kind:'character',id:p.id,name:p.name,detail:'Earliest recruitment · '+p.when});for(const m of M)if([m.name,m.location,m.ability,m.tip].join(' ').toLowerCase().includes(q))rs.push({kind:'materia',id:m.id,name:m.name,detail:'Materia · '+m.type});$('#searchResults').innerHTML=rs.length?rs.slice(0,50).map(r=>`<button class="search-result" data-result-kind="${r.kind}" data-result-id="${r.id}"><b>${esc(r.name)}</b><small>${esc(r.detail)}</small></button>`).join(''):'<div class="empty">No results. Try a location, item or boss name.</div>';}
function showSources(){$('#sourcesDialog').showModal();}
$('#sourceLinks').innerHTML=SOURCES.map(([t,d,u])=>`<a class="source-link" href="${u}" target="_blank" rel="noopener noreferrer">${esc(t)} ↗<small>${esc(d)}</small></a>`).join('');
$('#searchOpen').onclick=()=>{$('#searchDialog').showModal();search();$('#globalSearch').focus();};
$('#settingsOpen').onclick=()=>{$('#spoilerToggle').checked=state.hideFuture;$('#settingsDialog').showModal();};
$('#sourcesOpen').onclick=showSources;$('#footerSources').onclick=showSources;
$('#globalSearch').oninput=search;$('#chapterSearch').oninput=renderAside;
$('#mobileMenu').onclick=()=>$('#sidebar').classList.add('open');$('#mobileClose').onclick=()=>$('#sidebar').classList.remove('open');
$('#spoilerToggle').onchange=e=>{state.hideFuture=e.target.checked;save();render();};
$('#exportBtn').onclick=()=>{const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ffvii-field-journal.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Journal exported. Your journey is safe.');};
$('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1500000)throw Error('too large');const next=normalize(JSON.parse(await f.text()));if(!confirm('Replace this device’s progress and notes with this backup?'))return;state=next;disc=current().disc;save();render();$('#settingsMessage').textContent='Backup restored successfully.';toast('Your journal is restored.');}catch{$('#settingsMessage').textContent='Could not import. Choose a valid FFVII Field Guide JSON backup.';}finally{e.target.value='';}};
$('#resetBtn').onclick=()=>{if(!confirm('Clear all checklist progress, collected Materia and notes on this device? Export a backup first if you want to keep them.'))return;state=defaults();disc=1;view='guide';tab='route';questId=null;save();$('#spoilerToggle').checked=false;$('#settingsMessage').textContent='A new journey is ready.';render();toast('New playthrough started.');};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.close){$('#'+b.dataset.close).close();return;}if(b.dataset.chapter){openChapter(b.dataset.chapter);return;}if(b.dataset.view){nav(b.dataset.view);return;}if(b.dataset.disc){disc=+b.dataset.disc;$('#chapterSearch').value='';renderAside();return;}if(b.dataset.tab){tab=b.dataset.tab;render();return;}if(b.dataset.boss){bossTab=b.dataset.boss;render();return;}if(b.dataset.quest){openQuest(b.dataset.quest);return;}if(b.hasAttribute('data-back-quests')){nav('quests');return;}if(b.dataset.complete){const c=[...C,...Q].find(c=>c.id===b.dataset.complete),value=!isDone(c);c.steps.forEach((_,i)=>{state.checks[c.id+'-s'+i]=value;(c.details?.[i]||[]).forEach((_,j)=>state.details[c.id+'-s'+i+'-d'+j]=value)});save();render();toast(value?'Route objectives marked complete.':'Route objectives unchecked.');return;}if(b.dataset.focusCheck){changeCheck(b.dataset.focusCheck,true);return;}if(b.dataset.resultKind){$('#searchDialog').close();if(b.dataset.resultKind==='chapter')openChapter(b.dataset.resultId);else if(b.dataset.resultKind==='quest')openQuest(b.dataset.resultId);else if(b.dataset.resultKind==='alert'){missQuery=ALERTS.find(a=>a.id===b.dataset.resultId).name;missFilter='All';missDisc='All';missHideDone=false;nav('missables');}else if(b.dataset.resultKind==='character'){nav('characters');}else{const m=M.find(m=>m.id===b.dataset.resultId);matSearch=m.name;matType='All';matOwned=false;nav('materia');}return;}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.check)changeCheck(el.dataset.check,el.checked);if(el.dataset.owned){state.owned[el.dataset.owned]=el.checked;const caveIndex=CAVES.findIndex(c=>c[1]===M.find(m=>m.id===el.dataset.owned)?.name);if(caveIndex>=0)state.caves[caveIndex]=el.checked;save();$('#matCount').textContent=Object.values(state.owned).filter(Boolean).length+' / '+M.length+' collected';$('#materiaGrid').innerHTML=materiaTiles();}if(el.id==='matType'){matType=el.value;$('#materiaGrid').innerHTML=materiaTiles();}if(el.id==='matOwned'){matOwned=el.checked;$('#materiaGrid').innerHTML=materiaTiles();}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.note){state.notes[el.dataset.note]=el.value;save();}if(el.id==='matSearch'){matSearch=el.value;$('#materiaGrid').innerHTML=materiaTiles();}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#searchOpen').click();}});
function fromHash(){const h=location.hash.slice(1);if(C.some(c=>c.id===h)){state.chapter=h;state.revealed=Math.max(state.revealed,C.findIndex(c=>c.id===h));disc=current().disc;view='guide';save();}else if(Q.some(q=>q.id===h)){view='quests';questId=h;}else if(['guide','journey','quests','materia','missables','chocobos','characters'].includes(h)){view=h;questId=null;}render();}
window.addEventListener('hashchange',fromHash);fromHash();
